# Enem 2023, 1º dia, caderno azul: Linguagens (questões 1 a 45 do caderno). Duas provas no site:
# enem-2023-linguagens-ingles (1–5 = inglês) e enem-2023-linguagens-espanhol (1–5 = espanhol); 6–45 iguais nas duas.
# Poemas e letras como imagem (versos e direitos): Q2 (Donne), Q3 (Wang Ping), Q4 (Tato Laviera), Q2-es (Shirley Campbell),
# Q3-es (Quiroz y López), Q5-es (Orishas), Q13 (Mário de Andrade), Q18 (Caetano Veloso), Q28 (Roberta Estrela D'Alva), Q31 (Ana Martins Marques).
import sys, pathlib, re
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent / "tools"))
from enem_aj import carregar_enem, enunciado_enem, paragrafos_enem

D = carregar_enem("enem-2023-dia1-azul")
p = lambda *xs: "".join(f"<p>{x}</p>" for x in xs)
ap = lambda *xs: "".join(f'<p class="apoio">{x}</p>' for x in xs)
fonte = lambda x: f'<p class="fonte">{x}</p>'
tit = lambda x: f'<p class="apoio"><strong>{x}</strong></p>'
P = lambda n: paragrafos_enem(D[n])


def figs(*pares):
    return [{"arquivo": a, "alt": t} for a, t in pares]


def poema(n, alt, arq):
    par = P(n)
    f = [x for t, x in par if t == "fonte"][-1]
    cmd = [x for t, x in par if t in ("p", "titulo")][-1]
    return {"enunciado": f"[[fig:1]]{fonte(f)}" + p(cmd), "imagens": figs((arq, alt))}


def fig_antes(n, arq, alt):
    par = P(n)
    f = " ".join(x for t, x in par if t == "fonte")
    cmd = [x for t, x in par if t in ("p", "titulo")][-1]
    return {"enunciado": f"[[fig:1]]{fonte(f)}" + p(cmd), "imagens": figs((arq, alt))}


def Q_(n, materia, assunto, expl, tags=(), trocas=(), extra=None, alts=None):
    q = {"materia": materia, "assunto": assunto, "area": "Linguagens", "tags": list(tags), "numeroOriginal": int(str(n).split("-")[0]),
         "enunciado": enunciado_enem(D[n], trocas), "alternativas": dict(alts or D[n]["alternativas"]), "imagens": [], "explicacao": expl}
    if extra: q.update(extra)
    q["alternativas"] = {k: re.sub(r"\s*INSTRUÇÕES PARA A REDAÇÃO.*$", "", v) for k, v in q["alternativas"].items()}
    return q


